package com.amdocs.telecom.scheduler;import com.amdocs.telecom.util.DBConnection;import com.amdocs.telecom.service.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
public class BackgroundServices{public static class NetworkEvent implements Comparable<NetworkEvent>{public final String id,node,type,severity;public NetworkEvent(String i,String n,String t,String s){id=i;node=n;type=t;severity=s;}private int w(){return "CRITICAL".equals(severity)?0:"HIGH".equals(severity)?1:"MEDIUM".equals(severity)?2:3;}public int compareTo(NetworkEvent o){return Integer.compare(w(),o.w());}}private final BlockingQueue<NetworkEvent> q=new PriorityBlockingQueue<>();private final ExecutorService workers=Executors.newFixedThreadPool(3);private final ScheduledExecutorService schedule=Executors.newScheduledThreadPool(2);private final AtomicBoolean run=new AtomicBoolean(true);private final TicketService tickets=new TicketService();public void start(){workers.submit(()->{while(run.get())try{NetworkEvent e=q.take();processEvent(e);}catch(InterruptedException x){Thread.currentThread().interrupt();break;}catch(Exception x){x.printStackTrace();}});schedule.scheduleAtFixedRate(this::slaMonitor,30,30,TimeUnit.SECONDS);schedule.scheduleAtFixedRate(this::notificationProcessor,5,10,TimeUnit.SECONDS);workers.submit((Callable<Integer>)()->0); // Callable/Future demonstration
}public void submit(NetworkEvent e)throws SQLException{try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("INSERT INTO network_events(event_id,network_node,event_type,severity,event_time)VALUES(?,?,?,?,CURRENT_TIMESTAMP)")){p.setString(1,e.id);p.setString(2,e.node);p.setString(3,e.type);p.setString(4,e.severity);p.executeUpdate();}q.offer(e);}private synchronized void processEvent(NetworkEvent e)throws SQLException{if("LINK_DOWN".equals(e.type)||"CRITICAL".equals(e.severity))tickets.create("CUST100245","SVC1001","NETWORK_OUTAGE","Auto-created from network event "+e.id+" at "+e.node,"CRITICAL".equals(e.severity)?"CRITICAL":"HIGH",e.severity,"NetworkEventProcessor");try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("UPDATE network_events SET processed=TRUE WHERE event_id=?")){p.setString(1,e.id);p.executeUpdate();}}private void slaMonitor(){try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("SELECT ticket_id,customer_id,sla_deadline FROM trouble_tickets WHERE status NOT IN('RESOLVED','CLOSED','CANCELLED')")){try(ResultSet r=p.executeQuery()){while(r.next()){long mins=(r.getTimestamp(3).getTime()-System.currentTimeMillis())/60000;if(mins<=60){String type=mins<0?"SLA_BREACH":"SLA_WARNING";try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(recipient_id,message,notification_type)VALUES(?,?,?)")){n.setString(1,r.getString(2));n.setString(2,type+" for ticket "+r.getLong(1));n.setString(3,type);n.executeUpdate();}}}}}catch(Exception e){e.printStackTrace();}}private void notificationProcessor(){try(Connection c=DBConnection.getInstance().get();Statement s=c.createStatement()){s.executeUpdate("UPDATE notifications SET processed=TRUE WHERE processed=FALSE");}catch(Exception e){e.printStackTrace();}}public void stop(){run.set(false);workers.shutdownNow();schedule.shutdownNow();}}
